class Qwen3MoeExperts(nn.Module):
    """Collection of expert weights stored as 3D tensors.

    Parameters:
        config: Qwen3-MoE configuration defining expert tensor dimensions.
    """

    def __init__(self, config: Qwen3MoeConfig) -> None:
        """Create the packed expert parameters used by the official model.

        Parameters:
            config: Qwen3-MoE configuration with expert dimensions.
        """
        super().__init__()
        self.num_experts = config.num_experts
        self.hidden_dim = config.hidden_size
        self.intermediate_dim = config.moe_intermediate_size
        self.gate_up_proj = nn.Parameter(torch.empty(self.num_experts, 2 * self.intermediate_dim, self.hidden_dim))
        self.down_proj = nn.Parameter(torch.empty(self.num_experts, self.hidden_dim, self.intermediate_dim))

    def forward(
        self,
        hidden_states: torch.Tensor,
        top_k_index: torch.Tensor,
        top_k_weights: torch.Tensor,
    ) -> torch.Tensor:
        """Route flattened tokens through selected packed expert weights.

        Parameters:
            hidden_states: Flattened token states shaped ``[tokens, hidden_size]``.
            top_k_index: Selected expert indices per token.
            top_k_weights: Selected router probabilities per token.
        """
        final_hidden_states = torch.zeros_like(hidden_states)
        with torch.no_grad():
            expert_mask = F.one_hot(top_k_index, num_classes = self.num_experts)
            expert_mask = expert_mask.permute(2, 1, 0)
            expert_hit = torch.greater(expert_mask.sum(dim = (-1, -2)), 0).nonzero()

        for expert_idx in expert_hit:
            expert_idx = expert_idx[0]
            top_k_pos, token_idx = torch.where(expert_mask[expert_idx])
            current_state = hidden_states[token_idx]
            gate, up = F.linear(current_state, self.gate_up_proj[expert_idx]).chunk(2, dim = -1)
            current_hidden_states = F.silu(gate) * up
            current_hidden_states = F.linear(current_hidden_states, self.down_proj[expert_idx])
            current_hidden_states = current_hidden_states * top_k_weights[token_idx, top_k_pos, None]
            final_hidden_states.index_add_(0, token_idx, current_hidden_states.to(final_hidden_states.dtype))
        return final_hidden_states


class Qwen3MoeTopKRouter(nn.Module):
    """Official Qwen3-MoE softmax top-k router.

    Parameters:
        config: Qwen3-MoE configuration defining routing dimensions.
    """

    def __init__(self, config: Qwen3MoeConfig) -> None:
        """Create the packed router weight matrix.

        Parameters:
            config: Qwen3-MoE routing configuration.
        """
        super().__init__()
        self.top_k = config.num_experts_per_tok
        self.num_experts = config.num_experts
        self.norm_topk_prob = config.norm_topk_prob
        self.hidden_dim = config.hidden_size
        self.weight = nn.Parameter(torch.zeros(self.num_experts, self.hidden_dim))

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
        """Compute official full router logits and selected normalized scores.

        Parameters:
            hidden_states: Token states whose trailing dimension is hidden size.
        """
        hidden_states = hidden_states.reshape(-1, self.hidden_dim)
        router_logits = F.linear(hidden_states, self.weight)
        router_probs = F.softmax(router_logits, dtype = torch.float, dim = -1)
        router_top_value, router_indices = torch.topk(router_probs, self.top_k, dim = -1)
        if self.norm_topk_prob:
            router_top_value /= router_top_value.sum(dim = -1, keepdim = True)
        return router_logits, router_top_value.to(router_logits.dtype), router_indices


class Qwen3MoeBlock(nn.Module):
    """Official packed-expert sparse MoE block with router diagnostics.

    Parameters:
        config: Qwen3-MoE configuration defining experts and routing.
    """

    def __init__(self, config: Qwen3MoeConfig) -> None:
        """Create source-compatible router and packed experts.

        Parameters:
            config: Qwen3-MoE configuration with expert dimensions.
        """
        super().__init__()
        self.experts = Qwen3MoeExperts(config)
        self.gate = Qwen3MoeTopKRouter(config)

    def forward(self, hidden_states: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        """Run source-compatible sparse routing for a batch of hidden states.

        Parameters:
            hidden_states: Tensor shaped ``[batch, tokens, hidden_size]``.
        """
        batch_size, sequence_length, hidden_dim = hidden_states.shape
        hidden_states_reshaped = hidden_states.view(-1, hidden_dim)
        router_logits, routing_weights, selected_experts = self.gate(hidden_states_reshaped)
        final_hidden_states = self.experts(hidden_states_reshaped, selected_experts, routing_weights)
        return final_hidden_states.reshape(batch_size, sequence_length, hidden_dim), router_logits


class Qwen3MoeDecoderLayer(nn.Module):
    """Qwen3 attention followed by either dense or sparse feed-forward block."""

    def __init__(self, config: Qwen3MoeConfig, layer_idx: int) -> None:
        """Create one decoder layer.

        Parameters:
            config: Qwen3-MoE configuration.
            layer_idx: Decoder-layer index.
        """
        super().__init__()
        self.self_attn = Qwen3Attention(config, layer_idx)
        self.input_layernorm = Qwen3RMSNorm(config.hidden_size, config.rms_norm_eps)
        self.post_attention_layernorm = Qwen3RMSNorm(config.hidden_size, config.rms_norm_eps)
        self.is_dense = layer_idx in config.mlp_only_layers or layer_idx % config.decoder_sparse_step != 0
        self.mlp = (
            nn.Sequential(nn.Linear(config.hidden_size, config.intermediate_size, bias = False), nn.SiLU(), nn.Linear(config.intermediate_size, config.hidden_size, bias = False))
            if self.is_dense else Qwen3MoeBlock(config)
        )

    def forward(self, hidden_states: torch.Tensor, positions: tuple[torch.Tensor, torch.Tensor], mask: torch.Tensor | None, cache: KVCache | None, use_cache: bool) -> tuple[torch.Tensor, torch.Tensor | None]:
        """Apply attention and dense or MoE feed-forward residuals.

        Parameters:
            hidden_states: Input decoder states.
            positions: Standard RoPE cosine and sine tensors.
            mask: Optional 1/0 attention mask.
            cache: Optional K/V cache.
            use_cache: Whether to update the cache.
        """
        hidden_states = hidden_states + self.self_attn(self.input_layernorm(hidden_states), positions, mask, cache, use_cache)
        normalized = self.post_attention_layernorm(hidden_states)
        if self.is_dense:
            return hidden_states + self.mlp(normalized), None
        output, router_logits = self.mlp(normalized)
        return hidden_states + output, router_logits


class Qwen3MoeForCausalLM(nn.Module):
    """Self-contained Qwen3-MoE causal language model."""

    def __init__(self, config: Qwen3MoeConfig) -> None:
        """Create embeddings, routed decoder layers, and LM head.

        Parameters:
            config: Qwen3-MoE model configuration.
        """
        super().__init__()
        self.config = config
        self.embed_tokens = nn.Embedding(config.vocab_size, config.hidden_size, config.pad_token_id)
        self.rotary_emb = RotaryEmbedding(config)
        self.layers = nn.ModuleList([Qwen3MoeDecoderLayer(config, idx) for idx in range(config.num_hidden_layers)])
        self.norm = Qwen3RMSNorm(config.hidden_size, config.rms_norm_eps)
        self.lm_head = nn.Linear(config.hidden_size, config.vocab_size, bias = False)
        self.apply(self._init_weights)

    def _init_weights(self, module: nn.Module) -> None:
        """Initialize model parameters with the official normal scale.

        Parameters:
            module: Module visited during recursive initialization.
        """
        if isinstance(module, (nn.Linear, nn.Embedding)):
            nn.init.normal_(module.weight, mean = 0.0, std = self.config.initializer_range)
        elif isinstance(module, Qwen3MoeExperts):
            nn.init.normal_(module.gate_up_proj, mean = 0.0, std = self.config.initializer_range)
            nn.init.normal_(module.down_proj, mean = 0.0, std = self.config.initializer_range)

    def forward(self, input_ids: torch.Tensor, attention_mask: torch.Tensor | None = None, past_key_values: KVCache | None = None, use_cache: bool | None = None, labels: torch.Tensor | None = None, output_router_logits: bool | None = None) -> MoeCausalLMOutput:
        """Return logits, optional CE plus MoE loss, cache, and router diagnostics.

        Parameters:
            input_ids: Token IDs shaped ``[batch, tokens]``.
            attention_mask: Optional 1/0 valid-token mask.
            past_key_values: Optional cache from a previous decoding call.
            use_cache: Whether to create or update the cache.
            labels: Optional shifted causal-LM targets.
            output_router_logits: Whether to return router logits.
        """
        use_cache = self.config.use_cache if use_cache is None else use_cache
        output_router_logits = self.config.output_router_logits if output_router_logits is None else output_router_logits
        if use_cache and past_key_values is None:
            past_key_values = KVCache()
        past_length = past_key_values.get_seq_length() if past_key_values is not None else 0
        hidden_states = self.embed_tokens(input_ids)
        position_ids = torch.arange(past_length, past_length + input_ids.shape[1], device = input_ids.device).unsqueeze(0).expand(input_ids.shape[0], -1)
        positions = self.rotary_emb(hidden_states, position_ids)
        routers = []
        for layer in self.layers:
            hidden_states, router_logits = layer(hidden_states, positions, attention_mask, past_key_values, use_cache)
            if router_logits is not None:
                routers.append(router_logits)
        logits = self.lm_head(self.norm(hidden_states))
        loss = aux_loss = None
        if labels is not None:
            ce_loss = F.cross_entropy(logits[:, :-1].reshape(-1, self.config.vocab_size), labels[:, 1:].reshape(-1), ignore_index = -100)
            aux_loss = load_balancing_loss(tuple(routers), self.config.num_experts, self.config.num_experts_per_tok, attention_mask)
            loss = ce_loss + self.config.router_aux_loss_coef * aux_loss
        return MoeCausalLMOutput(logits, loss, aux_loss, past_key_values if use_cache else None, tuple(routers) if output_router_logits else None)
